def say(text, **o):
    SEQ.append((text, o))


def part(i): SEQ.append(('part', i))
def think(s=1.2): SEQ.append(('think', s))
def pause(s=0.6): SEQ.append(('pause', s))


# ================================================================================================ opening

import math
def _bell(x0, x1, base, h, skew, u0, u1, n=28):
    """points of the diffusion bell between fractions u0..u1 of its width (a gap in it is the chasm)"""
    return [(round(x0 + (x1 - x0) * u, 1), round(base - h * math.exp(-0.5 * ((u - 0.5 - skew) / 0.17) ** 2), 1)) for u in (u0 + (u1 - u0) * i / n for i in range(n + 1))]

